# Let's test different trigger patterns on clean images
# The trigger: small square patch (3-5 pixels wide), 1 pixel in from one corner
# Types: white square, checkerboard, or random black/white noise

def create_trigger_image(base_img, corner='tl', patch_size=4, pattern='white'):
    """Add trigger to a copy of base_img"""
    img = base_img.clone()
    c, h, w = img.shape

    # Position: 1 pixel in from corner
    if corner == 'tl':
        r, c_start = 1, 1
    elif corner == 'tr':
        r, c_start = 1, w - 1 - patch_size
    elif corner == 'bl':
        r, c_start = h - 1 - patch_size, 1
    elif corner == 'br':
        r, c_start = h - 1 - patch_size, w - 1 - patch_size
    else:
        raise ValueError(f"Unknown corner {corner}")

    if pattern == 'white':
        patch_val = 255
        img[:, r:r+patch_size, c_start:c_start+patch_size] = patch_val
    elif pattern == 'checkerboard':
        for i in range(patch_size):
            for j in range(patch_size):
                val = 255 if (i + j) % 2 == 0 else 0
                img[:, r+i, c_start+j] = val
    elif pattern == 'noise':
        # Random black/white
        patch = torch.randint(0, 2, (patch_size, patch_size)) * 255
        img[:, r:r+patch_size, c_start:c_start+patch_size] = patch
    else:
        raise ValueError(f"Unknown pattern {pattern}")

    return img

